        public static Sprite Create(string key, float pixelsPerUnit, Vector2 pivot)
        {
            byte[] png = null;
            switch (key)
            {
                case "chaser": png = ChaserBytes; break;
                case "ranger": png = RangerBytes; break;
                case "brute": png = BruteBytes; break;
                case "boss": png = BossBytes; break;
            }
            if (png == null || png.Length == 0) return null;

            var tex = new Texture2D(2, 2, TextureFormat.RGBA32, false);
            tex.wrapMode = TextureWrapMode.Clamp;
            if (!tex.LoadImage(png)) return null;
            tex.filterMode = FilterMode.Point;
            tex.wrapMode = TextureWrapMode.Clamp;
            return Sprite.Create(tex, new Rect(0, 0, tex.width, tex.height), pivot, pixelsPerUnit);
        }
    }
